const $=id=>document.getElementById(id),money=n=>n.toLocaleString('pt-BR',{style:'currency',currency:'BRL'});
const sizes=[[200,11.9],[300,16.9],[400,18.9],[500,22.9],[700,29.9]];
const free=['Paçoquita','Leite Ninho','Amendoim','Farinha de amendoim','Granola','Leite condensado','Granulado de chocolate','Granulado colorido','Chocoball','Sucrilhos','Aveia','Nescau Ball','Morango','Banana','Uva'];
const extras=[['Creme de Ninho',4],['Topo de Chantininho',4],['Borda de Chantininho',4],['Creme de Morango',3],['Creme de Maracujá',4],['Creme de Beijinho',3],['Topo de Nutella',8],['Borda de Nutella',8],['Creme de Pistache',8],['Creme de Ovomaltine',8],['Kiwi',4],['Doce de Leite',4.5],['Ovomaltine Flocos',3.5],['Ovomaltine Rocks',6]];
$('sizes').innerHTML=sizes.map(([v,p])=>`<div class="price-row"><span><b>${v} ml</b>${v===400?'<small>Mais vendido</small>':v===700?'<small>Melhor custo-benefício</small>':''}</span><strong>${money(p)}</strong></div>`).join('');
$('free').innerHTML=free.map(n=>`<span>${n}</span>`).join('');
$('extras').innerHTML=extras.map(([n,p])=>`<div class="price-row"><span>${n}</span><strong>${money(p)}</strong></div>`).join('');
['sizes','free','extras'].forEach(id=>$('fruit-'+id).innerHTML=$(id).innerHTML);
function normalize(s){return s.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase()}
function render(q=''){let count=0;$('menu').innerHTML=Object.entries(groups).map(([category,items])=>{const list=items.filter(i=>normalize(category+' '+i.name+' '+i.desc).includes(normalize(q)));count+=list.length;return list.length?`<section class="menu-section" id="${category}"><div class="section-title"><div><p class="eyebrow">${category==='Especiais'?'COMBINAÇÕES QUE DÃO MATCH · 500 ML':'MAIS SABORES DO ZÉ'}</p><h2>${category==='Especiais'?'Especiais do Zé':category}</h2></div></div><div class="cards">${list.map(i=>`<article class="card">${i.image?`<img loading="lazy" src="assets/${i.image}" alt="${i.name}" width="112" height="166">`:''}<div class="card-content"><h3>${i.name}</h3><p>${i.desc}</p><span class="price">${money(i.price)}</span></div></article>`).join('')}</div></section>`:''}).join('');let hasAcai=false;['acai','frutados'].forEach(id=>{const match=!q||normalize($(id).textContent).includes(normalize(q));$(id).hidden=!match;hasAcai=hasAcai||match});$('empty').hidden=count>0||hasAcai}
render();$('search').addEventListener('input',e=>{render(e.target.value)});
document.querySelectorAll('nav a').forEach(a=>a.addEventListener('click',()=>{if($('search').value){$('search').value='';render()}document.querySelectorAll('nav a').forEach(x=>x.classList.remove('active'));a.classList.add('active')}));
